function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const DEMAND_FORECAST_TABLE = 8; // 需要予測結果
  const ORDER_TABLE = 9; // 発注データ

  let currentOrderData = [];
  let selectedItems = new Set();

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#input-order-date').value = today;
  container.querySelector('#input-order-date').min = today;

  // 店舗データ読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(STORES_TABLE);
    if (stores) {
      const storeSelect = container.querySelector('#select-store');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      stores.filter(s => s.有効フラグ).forEach(store => {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      });
    }
  }

  // 商品カテゴリ読み込み
  async function loadCategories() {
    const products = await window.aivicApi.list(PRODUCTS_TABLE);
    if (products) {
      const categories = [...new Set(products.map(p => p.商品カテゴリID))];
      const categorySelect = container.querySelector('#select-category');
      categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>';
      categories.forEach(cat => {
        if (cat) {
          categorySelect.innerHTML += `<option value="${cat}">カテゴリ${cat}</option>`;
        }
      });
    }
  }

  // 発注データ表示
  function renderOrderData(data) {
    const tbody = container.querySelector('#order-tbody');

    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" class="muted">データがありません</td></tr>';
      updateTotalSection();
      return;
    }

    tbody.innerHTML = data.map(item => `
      <tr data-product-id="${item.商品ID}">
        <td><input type="checkbox" class="item-checkbox" data-product-id="${item.商品ID}" /></td>
        <td>${item.商品コード || ''}</td>
        <td>${item.商品名 || ''}</td>
        <td class="text-right">${item.予測数量 || 0}</td>
        <td class="text-right">${item.推奨発注数量 || 0}</td>
        <td class="text-right">${item.現在在庫数量 || 0}</td>
        <td>
          <input type="number" class="input quantity-input" 
                 data-product-id="${item.商品ID}"
                 value="${item.推奨発注数量 || 0}" 
                 min="0" step="1" />
          <div class="error-message hidden" data-error-for="${item.商品ID}"></div>
        </td>
        <td class="text-right">${item.発注単価 || 0}円</td>
        <td class="text-right amount-display" data-amount-for="${item.商品ID}">
          ${((item.推奨発注数量 || 0) * (item.発注単価 || 0)).toLocaleString()}円
        </td>
        <td>
          <button class="action-btn secondary single-order-btn" data-product-id="${item.商品ID}">
            個別発注
          </button>
        </td>
      </tr>
    `).join('');

    updateTotalSection();
  }

  // 発注データ取得
  async function loadOrderData() {
    const storeId = container.querySelector('#select-store').value;
    const orderDate = container.querySelector('#input-order-date').value;
    const categoryId = container.querySelector('#select-category').value;

    if (!storeId) {
      renderOrderData([]);
      return;
    }

    try {
      // 需要予測結果を取得
      const forecasts = await window.aivicApi.list(DEMAND_FORECAST_TABLE);
      const products = await window.aivicApi.list(PRODUCTS_TABLE);

      if (!forecasts || !products) {
        renderOrderData([]);
        return;
      }

      // 店舗と日付でフィルタリング
      let filteredForecasts = forecasts.filter(f => 
        f.店舗ID === storeId && 
        f.予測対象日 && 
        f.予測対象日.split('T')[0] === orderDate
      );

      // カテゴリでフィルタリング
      if (categoryId) {
        const categoryProducts = products.filter(p => p.商品カテゴリID === categoryId);
        const categoryProductIds = categoryProducts.map(p => p.商品ID);
        filteredForecasts = filteredForecasts.filter(f => 
          categoryProductIds.includes(f.商品ID)
        );
      }

      // 商品情報と結合
      const orderData = filteredForecasts.map(forecast => {
        const product = products.find(p => p.商品ID === forecast.商品ID);
        return {
          商品ID: forecast.商品ID,
          商品コード: product?.商品コード || '',
          商品名: product?.商品名 || '',
          予測数量: forecast.予測数量 || 0,
          推奨発注数量: forecast.推奨発注数量 || 0,
          現在在庫数量: Math.floor(Math.random() * 100), // 実際は在庫システムから取得
          発注単価: product?.単価 || 0
        };
      });

      currentOrderData = orderData;
      renderOrderData(orderData);

    } catch (error) {
      console.error('発注データ読み込みエラー:', error);
      renderOrderData([]);
    }
  }

  // 合計セクション更新
  function updateTotalSection() {
    const checkboxes = container.querySelectorAll('.item-checkbox:checked');
    const totalSection = container.querySelector('#total-section');
    const bulkOrderBtn = container.querySelector('#btn-bulk-order');

    if (checkboxes.length > 0) {
      totalSection.classList.remove('hidden');
      bulkOrderBtn.disabled = false;

      let totalAmount = 0;
      checkboxes.forEach(cb => {
        const productId = cb.dataset.productId;
        const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
        const item = currentOrderData.find(d => d.商品ID === productId);
        if (item && quantityInput) {
          const quantity = parseInt(quantityInput.value) || 0;
          totalAmount += quantity * (item.発注単価 || 0);
        }
      });

      container.querySelector('#selected-count').textContent = checkboxes.length;
      container.querySelector('#total-amount').textContent = totalAmount.toLocaleString();
    } else {
      totalSection.classList.add('hidden');
      bulkOrderBtn.disabled = true;
    }
  }

  // 発注金額計算
  function calculateAmount(productId, quantity) {
    const item = currentOrderData.find(d => d.商品ID === productId);
    if (!item) return 0;

    const amount = quantity * (item.発注単価 || 0);
    const amountDisplay = container.querySelector(`[data-amount-for="${productId}"]`);
    if (amountDisplay) {
      amountDisplay.textContent = `${amount.toLocaleString()}円`;
    }

    updateTotalSection();
    return amount;
  }

  // バリデーション
  function validateOrderQuantity(productId, quantity) {
    const errorDiv = container.querySelector(`[data-error-for="${productId}"]`);

    if (quantity === '' || quantity === null || quantity === undefined) {
      errorDiv.textContent = '発注数量を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (isNaN(quantity) || !Number.isInteger(Number(quantity))) {
      errorDiv.textContent = '数値を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (quantity < 0) {
      errorDiv.textContent = '発注数量は正の値を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (quantity === 0) {
      errorDiv.textContent = '発注数量は1以上の値を入力してください';
      errorDiv.classList.remove('hidden');
      return false;
    }

    if (quantity > 99999) {
      errorDiv.textContent = '発注数量が上限を超えています';
      errorDiv.classList.remove('hidden');
      return false;
    }

    errorDiv.classList.add('hidden');
    return true;
  }

  // 発注実行
  async function executeOrder(items) {
    const storeId = container.querySelector('#select-store').value;
    const orderDate = container.querySelector('#input-order-date').value;

    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    if (!orderDate || orderDate < today) {
      alert('発注日付は本日以降の日付を選択してください');
      return false;
    }

    const orders = [];
    for (const item of items) {
      const quantity = parseInt(item.quantity);
      if (!validateOrderQuantity(item.productId, quantity)) {
        return false;
      }

      const productData = currentOrderData.find(d => d.商品ID === item.productId);
      if (!productData) continue;

      const orderData = {
        店舗ID: storeId,
        商品ID: item.productId,
        発注日: new Date(orderDate).toISOString(),
        納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(), // 3日後
        発注数量: quantity,
        予測数量: productData.予測数量,
        発注単価: productData.発注単価,
        発注金額: quantity * productData.発注単価,
        発注方法: 'AI推奨採用',
        発注ステータス: '発注済',
        仕入先ID: 'supplier-001', // 実際は商品マスタから取得
        発注理由: 'AI需要予測に基づく発注',
        自動発注フラグ: false,
        作成者ID: 'current-user-id',
        更新者ID: 'current-user-id'
      };

      orders.push(orderData);
    }

    try {
      for (const order of orders) {
        await window.aivicApi.save(ORDER_TABLE, order);
      }

      alert(`${orders.length}件の発注を実行しました`);

      // 選択状態をクリア
      selectedItems.clear();
      container.querySelectorAll('.item-checkbox').forEach(cb => cb.checked = false);
      container.querySelector('#check-all').checked = false;
      updateTotalSection();

      return true;
    } catch (error) {
      console.error('発注実行エラー:', error);
      alert('発注実行中にエラーが発生しました');
      return false;
    }
  }

  // 確認モーダル表示
  function showConfirmModal(items) {
    const modal = container.querySelector('#order-confirm-modal');
    const detailsDiv = container.querySelector('#confirm-details');

    let totalAmount = 0;
    const details = items.map(item => {
      const productData = currentOrderData.find(d => d.商品ID === item.productId);
      const amount = item.quantity * (productData?.発注単価 || 0);
      totalAmount += amount;

      return `
        <div style="display: flex; justify-content: space-between; padding: 0.5rem 0; border-bottom: 1px solid var(--border);">
          <span>${productData?.商品名 || ''}</span>
          <span>${item.quantity}個 × ${(productData?.発注単価 || 0).toLocaleString()}円 = ${amount.toLocaleString()}円</span>
        </div>
      `;
    }).join('');

    detailsDiv.innerHTML = `
      <div style="margin-bottom: 1rem;">
        <strong>発注内容確認</strong>
      </div>
      ${details}
      <div style="display: flex; justify-content: space-between; padding: 1rem 0; font-weight: bold; font-size: 1.1rem; border-top: 2px solid var(--border);">
        <span>合計</span>
        <span>${totalAmount.toLocaleString()}円</span>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // 初期化
  loadStores();
  loadCategories();

  // イベントリスナー

  // 店舗選択変更
  container.querySelector('#select-store').addEventListener('change', loadOrderData);

  // 発注日付変更
  container.querySelector('#input-order-date').addEventListener('change', loadOrderData);

  // カテゴリ選択変更
  container.querySelector('#select-category').addEventListener('change', loadOrderData);

  // 表示更新ボタン
  container.querySelector('#btn-refresh').addEventListener('click', loadOrderData);

  // 全選択チェックボックス
  container.querySelector('#check-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.item-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedItems.add(cb.dataset.productId);
      } else {
        selectedItems.delete(cb.dataset.productId);
      }
    });
    updateTotalSection();
  });

  // 数量入力変更
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('quantity-input')) {
      const productId = e.target.dataset.productId;
      const quantity = parseInt(e.target.value) || 0;
      calculateAmount(productId, quantity);
    }
  });

  // チェックボックス変更
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('item-checkbox')) {
      const productId = e.target.dataset.productId;
      if (e.target.checked) {
        selectedItems.add(productId);
      } else {
        selectedItems.delete(productId);
      }
      updateTotalSection();
    }
  });

  // まとめて発注実行
  container.querySelector('#btn-bulk-order').addEventListener('click', () => {
    const selectedCheckboxes = container.querySelectorAll('.item-checkbox:checked');
    if (selectedCheckboxes.length === 0) {
      alert('発注する商品を選択してください');
      return;
    }

    const items = Array.from(selectedCheckboxes).map(cb => {
      const productId = cb.dataset.productId;
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
      return {
        productId: productId,
        quantity: parseInt(quantityInput.value) || 0
      };
    });

    showConfirmModal(items);
  });

  // 個別発注
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('single-order-btn')) {
      const productId = e.target.dataset.productId;
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 0;

      const items = [{
        productId: productId,
        quantity: quantity
      }];

      showConfirmModal(items);
    }
  });

  // モーダル確認ボタン
  container.querySelector('#btn-confirm-execute').addEventListener('click', async () => {
    const selectedCheckboxes = container.querySelectorAll('.item-checkbox:checked');
    const items = Array.from(selectedCheckboxes).map(cb => {
      const productId = cb.dataset.productId;
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
      return {
        productId: productId,
        quantity: parseInt(quantityInput.value) || 0
      };
    });

    // 個別発注の場合は選択されたボタンから取得
    if (items.length === 0) {
      const activeBtn = container.querySelector('.single-order-btn:focus');
      if (activeBtn) {
        const productId = activeBtn.dataset.productId;
        const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
        items.push({
          productId: productId,
          quantity: parseInt(quantityInput.value) || 0
        });
      }
    }

    const success = await executeOrder(items);
    if (success) {
      container.querySelector('#order-confirm-modal').classList.add('hidden');
    }
  });

  // モーダルキャンセルボタン
  container.querySelector('#btn-confirm-cancel').addEventListener('click', () => {
    container.querySelector('#order-confirm-modal').classList.add('hidden');
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#order-confirm-modal').addEventListener('click', (e) => {
    if (e.target.id === 'order-confirm-modal') {
      container.querySelector('#order-confirm-modal').classList.add('hidden');
    }
  });
}
